insert into public.concepts
  (id, term, aliases, said, alias_list, status, one_liner, analogy, example, related, deeper, lens_pm, lens_eng, domain, priority, tags)
values
  ('keypointdetection', 'Keypoint detection', '', '', ARRAY['keypoint','landmark detection']::text[], 'Rising', 'Spotting specific landmarks — eyes, joints, edges — in an image so the model knows where important parts are.', 'Like marking constellations on a star map: the model learns to highlight the brightest points in an image.', 'A pose estimator locates your shoulders, elbows, and knees so a fitness app can check your form during a workout.', '[{"text":"Closely paired with object detection and bounding boxes for spatial reasoning."}]'::jsonb, 'The model outputs coordinates for each landmark, often with confidence scores. Accuracy matters downstream — a missed shoulder throws off everything built on it. Modern approaches use heatmaps or regression heads to predict positions end-to-end.', 'Unlocks use cases that need to understand *where* things are, not just *what* they are — from fitness tracking to gesture control.', 'Output is typically a list of (x, y) coordinates or a heatmap per keypoint; training uses L2 loss or MSE on predicted positions.', 'Multimodal', 60, ARRAY['seed','multimodal']::text[]),
  ('documentunderstanding', 'Document understanding', '', '', ARRAY['document analysis','OCR','document intelligence','document processing']::text[], 'Rising', 'Teaching a model to read, parse, and extract meaning from PDFs, forms, receipts, and scanned pages.', 'Like hiring a careful librarian to skim a messy stack of papers and pull out the facts you need.', 'An invoice processor reads text and layout, finds the total amount, date, and vendor — then slots them into a database without manual entry.', '[{"text":"Builds on layout analysis to understand spatial structure.","id":"layoutanalysis"},{"text":"Text extraction step often leverages character recognition.","id":"handwritingrecognition"}]'::jsonb, 'Modern approaches combine vision (reading the layout and text position) with language (understanding context). Layout matters — where text sits on the page is semantic. Tables, headers, and field labels carry structure that pure OCR misses. Multimodal models excel here.', 'Shrinks manual data entry and unlocks automation for paper-heavy industries — finance, insurance, contracts.', 'Typically a pipeline: image → text extraction (OCR) → layout parsing → entity extraction + relation detection.', 'Multimodal', 60, ARRAY['seed','multimodal']::text[]),
  ('layoutanalysis', 'Layout analysis', '', '', ARRAY['document layout','spatial structure','layout understanding','page segmentation']::text[], 'Rising', 'Parsing the visual geometry of a page — where text blocks, images, and tables sit — to understand its structure.', 'Like looking at a newspaper and identifying which parts are the headline, body text, sidebar, and ads by their position and size.', 'A model ingests a form image and carves it into regions: "header area," "field labels," "input boxes" — then extracts text intelligently from each zone.', '[{"text":"Feeds into document understanding for semantic parsing.","id":"documentunderstanding"}]'::jsonb, 'Layout analysis typically outputs bounding boxes or masks for content regions. It''s the bridge between raw pixels and structured data. Reading order matters for multi-column documents. Modern approaches use object detection or segmentation on document images.', 'Makes document automation work at scale — the model understands *context* through spatial position, not just character recognition.', 'Feed images to a segmentation or detection model; output is usually region coordinates with class labels (heading, paragraph, table, etc.).', 'Multimodal', 60, ARRAY['seed','multimodal']::text[]),
  ('chartunderstanding', 'Chart understanding', '', '', ARRAY['chart reading','diagram understanding','plot interpretation','graph OCR']::text[], 'Rising', 'Extracting data and insight from visual plots — bar charts, line graphs, pie charts — so a model can answer questions about trends and values.', 'Reading a chart is like someone describing a pattern verbally: "sales went up last quarter" is richer than just the numbers.', 'A financial AI model looks at a revenue chart in a PDF report, identifies the trend line, and tells an analyst that Q3 dipped 15% compared to Q2.', '[{"text":"Part of broader document understanding workflow.","id":"documentunderstanding"}]'::jsonb, 'This is harder than it seems. Axes need interpretation (time scale, value scale), legend colors matter, and the model must infer relationships between visual elements. Some approaches use OCR on axis labels plus structural reasoning. Others train multimodal models end-to-end on chart-question-answer pairs.', 'Turns static images into queryable data — users ask questions of charts without manual transcription.', 'Combines vision (detecting axes, bars, lines) with NLP (interpreting labels). Output can be structured data or natural language answers.', 'Multimodal', 60, ARRAY['seed','multimodal']::text[]),
  ('handwritingrecognition', 'Handwriting recognition', '', '', ARRAY['handwriting OCR','character recognition','script recognition','cursive recognition']::text[], 'Fading', 'Converting cursive or printed handwriting into digital text, a classic problem that deep learning handles reasonably well now.', 'Like teaching someone to read messy, uneven handwriting — some strokes are ambiguous, but context helps.', 'A bank scans a handwritten check and automatically extracts the payee and amount, then validates against the account.', '[{"text":"Supports document understanding and form processing.","id":"documentunderstanding"}]'::jsonb, 'Handwriting is harder than print because individual variation is massive and strokes blur together. Models need context windows to disambiguate (is that an "a" or an "o"?). CTC loss and sequence models work well. Modern approaches often treat it as a sequence-to-sequence problem: image pixels → text tokens.', 'Enables paper-to-digital workflows in healthcare, banking, and logistics.', 'Feed cropped text regions or full forms to an image-to-text model (CNN + RNN or transformer). Train on datasets like MNIST, IAM Handwriting Database.', 'Multimodal', 30, ARRAY['seed','multimodal']::text[]),
  ('zeroshprompting', 'Zero-shot prompting', '', '', ARRAY['unfamiliar task','no examples','instruction only']::text[], 'Core', 'Giving a model a task with only instructions, no examples, and expecting it to figure it out on the first try.', 'Asking a smart stranger for directions to a place they''ve never been: they reason it out from first principles.', 'You ask a language model "Translate this to French:" and paste text, without showing it any translation examples first.', '[{"text":"Contrasts with few-shot and one-shot, where examples improve performance.","id":"fewshot"}]'::jsonb, 'Zero-shot works because modern LLMs are instruction-tuned — they learn to follow a wide variety of commands during training. It''s not magic: the model has seen countless examples of translations in its pretraining data and learned the pattern. Failure happens when the task is truly novel or requires specialized knowledge.', 'The easiest path to new use cases: no labeling, no examples to curate. Works for tasks similar to the model''s training distribution.', 'No prompt engineering needed, just clear instructions. Baseline performance is often decent; few-shot or fine-tuning helps only if performance gaps are large.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('prompttemplate', 'Prompt template', '', '', ARRAY['prompt skeleton','prompt pattern','reusable prompt','prompt boilerplate']::text[], 'Core', 'A reusable prompt structure with placeholders for variable content — the skeleton of many prompts you''ll write.', 'Like a form letter: fixed instruction sections and variable slots for names, dates, and details.', 'Template: "You are an expert [ROLE]. Answer the question: [QUESTION]. Format as: [FORMAT]." Then plug in role, question, and format each time.', '[{"text":"Foundation for dynamic prompting and prompt registry systems.","id":"dynamicprompting"}]'::jsonb, 'Templates reduce repetition and encourage consistency. They''re especially useful in production systems where the same prompt pattern serves many inputs. Template variables can be simple (string interpolation) or complex (conditional sections). Version control templates like code.', 'Standardizes quality and cost across many calls; easier to iterate and A/B test.', 'Can be implemented as Python string templates, Jinja, or a prompt management tool. Track template versions and A/B test results by version.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('roleprompting', 'Role prompting', '', '', ARRAY['persona prompting','role-playing','character prompting','identity assignment']::text[], 'Core', 'Telling the model to adopt a specific role — expert, critic, mentor — to change the tone and quality of its output.', 'Asking different people to answer: a teacher explains differently than a comedian or an engineer.', '"You are a senior software architect. Review this code for maintainability and scalability issues." vs. just "Review this code."', '[{"text":"A specific type of persona technique.","id":"personaprompting"}]'::jsonb, 'Role prompts work because the model learned associations between identities and knowledge/style during training. A "helpful tutor" persona elicits explanatory text; a "security engineer" persona spots attack vectors. The role acts as shorthand for a behavioral mode. Combining roles with other techniques (few-shot, CoT) stacks effects.', 'Cheap way to steer output tone and depth; often improves perceived quality without model changes.', 'Just text in the system message. Combine with other constraints. Watch for role hallucination if you ask too specific a persona.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('selfconsistency', 'Self-consistency', '', '', ARRAY['consistency voting','majority voting','path aggregation','ensemble reasoning']::text[], 'Core', 'Running the same prompt multiple times and taking a vote on the answer, boosting accuracy when reasoning is involved.', 'Asking the same question to the same person ten times; their answers agree more often for true facts than for guesses.', 'Ask "What is 7 × 13?" five times with temperature=0.7; four times you get 91, once you get 89. Trust the majority.', '[{"text":"Leverages temperature and sampling diversity.","id":"sampling"}]'::jsonb, 'Self-consistency amplifies the effect of temperature and sampling. At high temperature, the model samples different reasoning paths; some reach right answers, some wrong ones. Voting on the final answer is surprisingly effective for math and logic. Costs more (5–10× calls), but accuracy can jump 10–30% on hard problems.', 'Improves reliability for critical tasks (medical diagnosis, code review, math) with compute trade-off: 5x cost for much higher confidence.', 'Call model 5–10 times, parse results, count correct answers. Use temperature ≥ 0.5 to induce diversity; temperature=0 gives the same answer every time.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('structuredoutput', 'Structured output', '', '', ARRAY['structured format','schema enforcement','constrained generation','typed output']::text[], 'Core', 'Forcing a model to output data in a specific format — JSON, XML, or a validated schema — instead of free-form text.', 'Like asking for a form filled out neatly instead of a rambling paragraph.', 'Prompt: "Return a JSON object with keys name, age, email." The model outputs `{"name": "Alice", "age": 30, "email": "..."}` guaranteed.', '[{"text":"JSON mode is one implementation of structured output.","id":"jsonmode"}]'::jsonb, 'Some APIs support constrained generation or JSON mode that hard-limits token choices to valid JSON sequences. Others use parsing + regeneration: generate text, parse it, if invalid ask again. Quality and speed matter — true schema enforcement is faster and more reliable than post-hoc parsing.', 'Unblocks downstream automation: once output is JSON, it''s machine-readable, no brittleness.', 'Use model API''s JSON mode if available (faster, guaranteed valid). Else: prompt clearly, add error handling, regenerate invalid outputs.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('jsonmode', 'JSON mode', '', '', ARRAY['JSON output','forced JSON','schema mode','structured JSON']::text[], 'Core', 'A model API feature that guarantees the output is valid JSON by constraining token choices during generation.', 'Like autocorrect that prevents you from typing invalid JSON.', 'OpenAI API: set `response_format: { type: "json_object" }` and the output will always parse with `json.loads()`.', '[{"text":"Implementation of structured output.","id":"structuredoutput"},{"text":"Output schema is the broader pattern.","id":"outputschema"}]'::jsonb, 'Under the hood, JSON mode works by blacklisting tokens that would break JSON syntax at each step. First `{` locks you into an object; once you type a key string, only `:` and certain characters follow. It''s elegant and fast. Downside: it doesn''t validate against a schema, only that the JSON is well-formed. A nested object might not match your expected structure.', 'Eliminates parsing errors; integrations work seamlessly.', 'Check your API docs. Combine with a schema definition (TypeScript type, Pydantic model) in the prompt. Parse the output confidently with no try/catch.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('outputparsing', 'Output parsing', '', '', ARRAY['response parsing','extraction','post-processing','result parsing']::text[], 'Core', 'Taking model output (text, JSON, XML) and pulling out the parts you need for downstream logic.', 'Like reading a letter, finding the relevant sentence, and extracting the answer.', 'Model outputs "The answer is 42." You regex-match or parse to extract the number 42.', '[{"text":"Unnecessary if you enforce structured output or JSON mode.","id":"jsonmode"}]'::jsonb, 'Parsing can be brittle if the model''s format is inconsistent. Structured output (JSON mode) reduces brittleness. LangChain and similar libraries offer parsers that handle common formats and recover from minor mistakes. The trick: prompt clearly for format, then validate aggressively.', 'Glue between model output and your application. Reliability is critical.', 'Use a parsing library if available (LangChain, Instructor). Add validation and error handling. Test edge cases.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('citation', 'Citation', '', '', ARRAY['citations','quote attribution','evidence attribution','source reference']::text[], 'Core', 'Asking a model to reference specific sources or quote passages from documents when making claims.', 'Like academic footnotes: every claim points back to where it came from.', '"According to *Document A, page 3*: ''The policy took effect January 1.''" vs. just "The policy took effect January 1."', '[{"text":"Works best with RAG and grounding.","id":"rag"},{"text":"Reduces hallucination.","id":"hallucination"}]'::jsonb, 'Citations reduce hallucination when grounding is available (e.g., with RAG). The model outputs text and source spans. This is harder than it sounds: the model must track which input came from where, and synthesized or paraphrased text breaks naive citation. Some approaches use token-level attention or explicit prompting to force citation.', 'Builds trust. Users see where facts come from. Regulatory requirement in some industries.', 'Prompt with structured input marking source boundaries. Parse output to extract quotes + source refs. Validate that quotes actually appear in the source.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('guardrailprompt', 'Guardrail prompt', '', '', ARRAY['safety prompt','alignment prompt','constraint prompt','boundary prompt']::text[], 'Rising', 'A prompt section that sets boundaries — what the model should and shouldn''t do — to prevent misuse.', 'House rules posted on the wall: "No shoes on the couch."', '"Do not help with illegal activities. Do not generate explicit content. Only discuss topics X, Y, Z."', '[{"text":"Related to refusal training.","id":"refusaltraining"},{"text":"Part of safety fine-tuning.","id":"safetyfinetuning"}]'::jsonb, 'Guardrails are part of system prompts or safety fine-tuning. Alone, they''re easily jailbroken if the user tries hard. They''re a first line of defense, not a security layer. Effective guardrails are specific, clear, and backed by training (RLHF). Adversarial examples can bypass even well-tuned guardrails.', 'Reduces harm and liability. Combined with other safety measures, important for public-facing systems.', 'Use clear, specific language. Monitor for jailbreaks. Combine with other safeguards (monitoring, human review). Never rely on prompts alone.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('metaprompting', 'Meta-prompting', '', '', ARRAY['prompting about prompts','recursive prompting','prompt generation','self-prompting']::text[], 'Rising', 'Using a model to generate or refine prompts for itself or other models — prompting about prompting.', 'Like a writer editing their own instructions to make them clearer.', 'You give Claude a task and ask: "Generate the best system prompt for an AI that does X." It writes a refined prompt you can reuse.', '[{"text":"Related to prompt optimization and automatic prompt engineering.","id":"promptoptimization"}]'::jsonb, 'Meta-prompting is a form of in-context learning and reflection. The model reasons about what instructions work. It can also be used for prompt optimization: iteratively improve a prompt by having the model critique and regenerate it. This is experimental and cost-intensive, but can yield domain-specific prompts better than hand-written ones.', 'Automates prompt engineering; useful for discovering patterns.', 'Implement a loop: generate prompt → test → critique → refine. Measure impact with a held-out eval set.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('promptchaining', 'Prompt chaining', '', '', ARRAY['chained prompts','sequential prompting','multi-step prompting','pipeline prompts']::text[], 'Core', 'Breaking a complex task into steps and feeding each output as input to the next prompt, like a pipeline.', 'Assembly line: raw material → stage 1 → stage 2 → stage 3 → finished product.', '"Summarize this article." → "Identify 3 key claims." → "Fact-check each claim using web search." → "Output final verdict."', '[{"text":"Foundation for agentic workflows.","id":"agents"},{"text":"Enables decomposition prompting.","id":"decompositionprompting"}]'::jsonb, 'Chaining works because complex tasks are easier when decomposed. Each step is simpler, reducing errors. Downsides: cost multiplies with steps, and errors in early steps cascade. You can parallelize independent branches or use branching logic (if error, retry; if success, proceed).', 'Improves reliability for multi-stage tasks. Enables workflow automation.', 'Orchestrate with conditional logic. Handle failures and retries. Log intermediate results for debugging.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('chatbot', 'Chatbot', '', '', ARRAY['conversational bot','chat agent','dialogue system','conversational interface']::text[], 'Core', 'A system that conducts a text (or voice) conversation with users, remembering context across turns.', 'A friend you can text anytime; they remember what you''ve said and respond thoughtfully.', 'ChatGPT: you ask questions, it answers, you follow up, it understands the prior context.', '[{"text":"Multi-turn is the core interaction pattern.","id":"multiturn"},{"text":"Assistant persona defines behavior.","id":"assistantpersona"}]'::jsonb, 'Modern chatbots are language models with conversation history in the context window. Earlier systems used intent classification + template responses. Today''s best-in-class use instruction-tuned LLMs. Key challenges: managing context length, handling off-topic or adversarial input, maintaining personality, and staying relevant over long conversations.', 'First point of contact for customer support, onboarding, and engagement.', 'Keep a message buffer (system + user/assistant turns). Feed full history to the model each turn. Manage token limits.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('conversationalai', 'Conversational AI', '', '', ARRAY['conversational agents','dialogue AI','chat AI','conversational NLP']::text[], 'Core', 'AI systems designed to understand and respond naturally in multi-turn conversations, mimicking human dialogue.', 'A very attentive friend who learns your preferences and responds naturally, not robotically.', 'Alexa, Siri, or a company chatbot that understands context, clarifies questions, and adapts tone.', '[{"text":"Chatbot is a narrower category.","id":"chatbot"},{"text":"Multi-turn is the interaction pattern.","id":"multiturn"},{"text":"Relies on instruction following.","id":"instructionfollowing"}]'::jsonb, 'Conversational AI combines NLP (understanding user intent), context management (remembering prior turns), and generation (producing fluent responses). Modern systems use LLMs with conversation history. Challenges include context length limits, handling ambiguity, recognizing when to ask clarifying questions, and avoiding repeating past mistakes.', 'Core experience for voice assistants, customer support, and engagement.', 'Use history-aware models. Implement context summarization for long conversations. Monitor user satisfaction.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('multiturn', 'Multi-turn', '', '', ARRAY['multi-turn conversation','multiple turns','dialogue turns','turn-taking']::text[], 'Core', 'A conversation where user and assistant exchange multiple messages, building context with each turn.', 'Tennis rally: user serves, assistant returns, user hits again, etc.', 'User: "What''s the capital of France?" Assistant: "Paris." User: "How many people live there?" Assistant: "About 2.1 million."', '[{"text":"Core to chatbots and conversational AI.","id":"chatbot"}]'::jsonb, 'Multi-turn requires managing conversation state: remembering prior messages, understanding pronouns and references, and adapting based on feedback. Context windows limit how many turns fit. Solutions: summarization, sliding window, or external memory. Token cost scales with conversation length.', 'Natural interaction. Users expect to refine questions and build on answers.', 'Implement message history buffer. Watch token limits. Summarize old conversations if too long.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('assistantpersona', 'Assistant persona', '', '', ARRAY['assistant personality','bot personality','character traits','personality definition']::text[], 'Core', 'Defining how an AI assistant should sound and behave — its tone, values, and communication style.', 'Casting an actor for a role: defining how they should deliver lines.', 'Persona: "You are helpful, witty, and concise. You avoid jargon and explain clearly. You are honest about limitations."', '[{"text":"Role prompting is a specific technique.","id":"roleprompting"}]'::jsonb, 'Personas are encoded in system prompts and training (RLHF, instruction tuning). A well-defined persona improves consistency and user trust. Personas can be specific (a pirate, a therapist, a data scientist) or abstract (helpful, harmless, honest). Over-specific personas can cause hallucination.', 'Shapes user perception and engagement. Consistency builds trust.', 'Define clearly in system prompt. Test across diverse inputs. Monitor for off-character outputs.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('promptlibrary', 'Prompt library', '', '', ARRAY['prompt repository','prompt collection','prompt database','prompt management system']::text[], 'Rising', 'A centralized collection of prompts — templates, system messages, examples — that teams reuse and version control.', 'Like a recipe book: save good prompts, label them, share with teammates.', 'A prompt library with "customer_support_agent", "blog_writer", "code_reviewer", each versioned and tested.', '[{"text":"Foundation for prompt versioning and optimization.","id":"promptversioning"}]'::jsonb, 'Prompt libraries improve consistency and reduce duplication. They enable collaboration, A/B testing, and iterative improvement. Tools like Prompt Flow, LangSmith, or custom Git-based systems manage this. Challenges: versioning, documentation, and measuring which prompts work best.', 'Standardizes quality across products. Speeds up new feature deployment.', 'Use version control. Document each prompt''s purpose, examples, and performance baselines. Test before adding.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('promptoptimization', 'Prompt optimization', '', '', ARRAY['prompt tuning','prompt improvement','prompt refinement','engineering optimization']::text[], 'Rising', 'Iteratively improving a prompt — through testing, measurement, and refinement — to boost model performance on a task.', 'Tweaking a recipe to get better results: adjust salt, temperature, and timing.', 'Test two versions of a prompt with 100 examples. Version A scores 87%, version B scores 92%. Use version B and iterate further.', '[{"text":"Automatic prompt engineering is one approach.","id":"automaticpromptengineering"}]'::jsonb, 'Optimization can be manual (prompt engineering) or automatic (using another model to generate/improve prompts, or using gradient-based search on soft prompts). Metrics matter: define what "better" means (accuracy, latency, cost). A/B testing with real users is the gold standard but requires scale.', 'Lifts performance without retraining models. Quick wins for existing systems.', 'Set up eval harness. Benchmark prompts systematically. Track versions and scores. Automate if possible (e.g., LLM-as-judge for scoring).', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('automaticpromptengineering', 'Automatic prompt engineering', '', '', ARRAY['APE','automatic optimization','prompt search','prompt synthesis']::text[], 'Rising', 'Using algorithms (often other LLMs) to automatically generate and refine prompts, replacing manual trial-and-error.', 'A machine that writes recipes, tests them, and iterates — faster than a human chef.', 'APE: give it a task and a small eval set, it generates 100 candidate prompts, scores them, and returns the best.', '[{"text":"Part of prompt optimization workflow.","id":"promptoptimization"},{"text":"Uses meta-prompting techniques.","id":"metaprompting"}]'::jsonb, 'Common approaches: (1) LLM generates candidate prompts; (2) Evaluate on test set; (3) Mutate top prompts and repeat. Challenges: eval set quality (small sets are noisy), cost (evaluating many prompts is expensive), and transferability (best prompt for one model/task may not work for another).', 'Faster iteration, less manual effort, sometimes better prompts.', 'Use libraries like DSPy or custom scripts. Set up robust eval metrics. Validate on held-out data.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('prompttuning', 'Prompt tuning', '', '', ARRAY['soft prompting','trainable prompts','prompt optimization','trainable prefixes']::text[], 'Core', 'Learning a "soft prompt" — a sequence of embedding vectors — instead of hand-writing text instructions.', 'Instead of typing "Be nice," training the model to recognize a learned signal that means "be nice."', 'Initialize 20 vectors, train them on your task data, use them as a prefix to the model. Often outperforms hand-crafted prompts.', '[{"text":"Related to soft prompts and prefix tuning.","id":"softprompts"}]'::jsonb, 'Soft prompts bypass the discrete token constraint. You optimize vectors end-to-end using gradient descent on your task loss. Pros: often outperforms handwriting, no token budget limits. Cons: less interpretable, not transferable across models, requires labeled data and compute.', 'Better performance for specialized tasks. Faster than fine-tuning.', 'Implement with a trainable embedding layer. Use gradient-based optimization. Save and reload the soft prompt for inference.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('softprompts', 'Soft prompts', '', '', ARRAY['embedding prompts','vector prompts','continuous prompts','learned instructions']::text[], 'Rising', 'Embedding vectors that act like prompts — learned during training rather than written as text.', 'A melody hummed (learned) vs. a song title spoken (written).', 'Instead of "Classify this as positive or negative," the model processes learned vectors that implicitly instruct classification.', '[{"text":"Core technique in prompt tuning.","id":"prompttuning"},{"text":"Related to prefix tuning.","id":"prefixtuning"}]'::jsonb, 'Soft prompts are prefixed to the model''s input embeddings. They''re optimized via backprop. Advantage: they exploit the model''s embedding space fully. Disadvantage: black box — you can''t inspect or transfer them. Effective for task-specific adaptation without fine-tuning the full model.', 'Lightweight adaptation for domain-specific tasks.', 'Implement as a learnable embedding layer. Train on task-specific data with a loss function. Validate generalization.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('prefixtuning', 'Prefix tuning', '', '', ARRAY['prefix learning','learnable prefixes','prefix prompts','prefix adaptation']::text[], 'Rising', 'A parameter-efficient method where you learn a short "prefix" of embeddings prepended to every layer, tuning the model for a task.', 'Whispering a hint in someone''s ear before they answer every question.', 'Train 100 vectors (the prefix) per layer to steer GPT-2 toward a task like summarization, using only 0.1% of the model''s parameters.', '[{"text":"Related to soft prompts and prompt tuning.","id":"softprompts"}]'::jsonb, 'Unlike full fine-tuning, prefix tuning keeps the model''s parameters frozen and only optimizes a learned prefix. This is parameter-efficient, making it attractive for systems with many tasks. Downside: the prefix needs to be specific to the base model; changing the model requires retuning.', 'Multi-task systems with shared base models and task-specific prefixes.', 'Implement with learnable prefix tensors. Use gradient descent to optimize. Monitor for overfitting on small tasks.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('delimiter', 'Delimiter', '', '', ARRAY['separator','boundary marker','section delimiter','input delimiter']::text[], 'Core', 'Special characters or markers that separate different sections of a prompt — user input from instructions, one example from another.', 'Using <----> to mark where one paragraph ends and the next begins.', 'Prompt: "Instructions: ...\n\n### INPUT\nUser query here\n\n### OUTPUT\nExpected format" — the ### marks section boundaries.', '[{"text":"Part of structured output design.","id":"structuredoutput"}]'::jsonb, 'Delimiters reduce ambiguity. They signal to the model where parsing should change. Common delimiters: newlines, ```, ###, tags (<input>, </input>). They''re especially useful when input contains special characters that might confuse the model.', 'Improves reliability when input is noisy or adversarial.', 'Choose a delimiter unlikely to appear in user input. Document it in your prompt template. Use consistently.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('fewshotexamples', 'Few-shot examples', '', '', ARRAY['in-context examples','demonstration','exemplars','few-shot instances']::text[], 'Core', 'Concrete input-output pairs included in a prompt to show the model how to do a task by example.', 'Showing someone how to tie a shoe with a demo before they try.', 'Prompt: "Classify as positive or negative:\nExample 1: ''I love this!'' → Positive\nExample 2: ''Terrible experience.'' → Negative\nNow classify: ''It''s OK.'' →"', '[{"text":"Part of in-context learning.","id":"incontextlearning"},{"text":"Exemplar selection optimizes choice.","id":"exemplarselection"}]'::jsonb, 'Few-shot learning (in-context learning) is one of LLMs'' superpowers. A model can learn task patterns from just 1–5 examples without retraining. Quality of examples matters: diverse, balanced, and representative examples work best. Too many examples waste token budget; too few leave the model confused.', 'Quick way to adapt a model to new tasks. No retraining needed.', 'Curate examples carefully. Test with different numbers and orders of examples. Monitor sensitivity.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('exemplarselection', 'Exemplar selection', '', '', ARRAY['example selection','demonstration selection','few-shot selection','dynamic selection']::text[], 'Rising', 'Choosing which examples to include in a few-shot prompt — diversity, relevance, and order all matter.', 'Picking which photos to show in a portfolio; you choose diverse, impressive shots, not random ones.', 'For a task, select examples that are similar to the test input (relevant) but diverse in edge cases (coverage).', '[{"text":"Improves few-shot prompting.","id":"fewshotexamples"}]'::jsonb, 'Naive few-shot uses random examples; smarter selection uses similarity to the test input (semantic matching) or active learning principles (uncertain cases). Optimal strategies are task-dependent. Research shows careful selection can boost performance 5–15% over random.', 'Squeeze more value from few-shot prompts with minimal cost.', 'Compute embeddings of examples and test input. Select k-nearest neighbors or maximize diversity. Experiment with strategies.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('instruction', 'Instruction', '', '', ARRAY['task instruction','command','directive','task description']::text[], 'Core', 'A clear, direct request that tells the model what to do — the most basic building block of a prompt.', 'A recipe instruction: "Chop the onions finely."', '"Summarize this article in one paragraph." or "Generate a creative product name."', '[{"text":"Paired with constraints and format specs.","id":"constraint"}]'::jsonb, 'Good instructions are specific, actionable, and unambiguous. Vague instructions like "Make it better" fail. Clear instructions like "Improve readability by using shorter sentences and active voice" work. Instruction quality is the single biggest driver of model output quality.', 'Foundation of prompt quality. Invest here.', 'Write clearly. Be specific. Test and iterate. Use examples if needed.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('constraint', 'Constraint', '', '', ARRAY['limitation','restriction','rule','boundary']::text[], 'Core', 'A restriction placed on the model — length, style, content rules — to shape output.', 'Like a painting competition: "Portrait only, max 500x500 pixels, pastels only."', '"Summarize in 2 sentences." "Do not use technical jargon." "Answer only with yes or no."', '[{"text":"Paired with instructions and format specs.","id":"instruction"}]'::jsonb, 'Constraints narrow the output space, making it easier for the model to satisfy requirements. Soft constraints (suggested) are easier to ignore than hard constraints (enforced). Some models support hard constraints via structured output or token limiting.', 'Ensures outputs fit requirements (length, format, content rules).', 'Add to instructions or enforce via output validation.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('formatspecification', 'Format specification', '', '', ARRAY['output format','format constraints','response format','output specification']::text[], 'Core', 'Explicitly defining how output should be structured — markdown, JSON, bullet points, etc.', 'Like saying "write as a shopping list" vs. "write as a paragraph."', '"Output as JSON: {name, age, occupation}." or "Format as a bulleted list with 3–5 items."', '[{"text":"Overlaps with structured output.","id":"structuredoutput"},{"text":"Related to output schema.","id":"outputschema"}]'::jsonb, 'Format specs reduce ambiguity and enable parsing. Structured formats (JSON, XML) are machine-readable. Natural formats (markdown, bullets) are human-readable. Combine format specs with examples or templates for clarity.', 'Enables downstream automation and consistent user experience.', 'Use structured output or JSON mode when possible. Validate parsed results.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('personaprompting', 'Persona prompting', '', '', ARRAY['persona','character adoption','role adoption','persona definition']::text[], 'Core', 'Explicitly telling the model to adopt a character or perspective — doctor, poet, skeptic — to shape reasoning and tone.', 'Method acting: the model immerses itself in a character.', '"You are a seasoned detective. Analyze this crime scene." vs. just "Analyze this crime scene."', '[{"text":"Related to role prompting.","id":"roleprompting"},{"text":"Assistant persona defines the bot''s character.","id":"assistantpersona"}]'::jsonb, 'Personas work by leveraging associations learned during training. A "data scientist" persona elicits analytical language. A "therapist" persona elicits empathy. Personas can be combined with other techniques. Over-specific personas ("a 400-year-old vampire who codes in Rust") may cause hallucination.', 'Inexpensive way to steer behavior and tone.', 'Test personas for consistency. Avoid hallucination in overly specific personas.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('stepbystepprompting', 'Step-by-step prompting', '', '', ARRAY['step-by-step reasoning','sequential reasoning','breaking down','step decomposition']::text[], 'Core', 'Explicitly asking the model to work through a task step-by-step, slowing down reasoning and reducing mistakes.', 'A parent asking a child to explain their math work step-by-step, not just give the answer.', '"Solve step-by-step: 5×(3+2) = ?" Model: "Step 1: Solve inside parens: 3+2=5. Step 2: Multiply: 5×5=25."', '[{"text":"Related to chain-of-thought and decomposition.","id":"chainofthought"},{"text":"Decomposes tasks into substeps.","id":"decompositionprompting"}]'::jsonb, 'Step-by-step reasoning (sometimes called "scratchpad") forces intermediate outputs, making reasoning visible and checkable. It works for logic puzzles, math, and fact-based tasks. Less effective for open-ended generation. Chain-of-thought (CoT) prompting is a formalization of this.', 'Boosts accuracy on reasoning tasks with minimal prompt changes.', 'Add "Let''s think step-by-step" or similar phrasing. Parse intermediate outputs if you need to validate.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('leasttomostprompting', 'Least-to-most prompting', '', '', ARRAY['least-to-most','progressive prompting','hierarchical prompting','problem progression']::text[], 'Rising', 'Breaking a hard problem into easier sub-problems, solving simplest first, then using solutions to tackle harder ones.', 'Learning to multiply: first practice single-digit facts, then two-digit numbers, then large multiplication.', 'For "write a 1000-word essay," first write a 1-sentence outline, then a 1-paragraph draft, then expand to 1000 words.', '[{"text":"Related to decomposition and step-by-step reasoning.","id":"decompositionprompting"},{"text":"Related to prompt chaining.","id":"promptchaining"}]'::jsonb, 'Least-to-most is effective because it mitigates error accumulation. Solve the base case well, then leverage it. A model that struggles with a hard task may excel if broken into easy substeps. Structured prompting can automate this decomposition.', 'Surprisingly effective for complex tasks. Minimal prompt overhead.', 'Manually decompose tasks. Use a second model to auto-decompose if possible.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('decompositionprompting', 'Decomposition prompting', '', '', ARRAY['problem breakdown','hierarchical decomposition','divide and conquer','subtask splitting']::text[], 'Rising', 'Breaking a complex task into smaller, simpler subtasks that a model can tackle independently.', 'Tackling a large project by breaking it into milestones.', '"Write an essay" → "Outline the thesis," "Write introduction," "Write body," "Write conclusion," "Proofread."', '[{"text":"Executed via prompt chaining.","id":"promptchaining"},{"text":"Related to least-to-most prompting.","id":"leasttomostprompting"}]'::jsonb, 'Decomposition reduces cognitive load on the model. Complex reasoning often fails end-to-end but succeeds when broken into steps. Downsides: more prompt calls (higher cost), error propagation (if step 1 is wrong, step 2 suffers). LLMs excel at planning decomposition; use one to plan, then execute.', 'Improves reliability on hard tasks.', 'Manually define decomposition or use an LLM to plan it. Implement error handling and recovery.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('selfask', 'Self-ask', '', '', ARRAY['self-questioning','asking follow-ups','self-dialogue','recursive questioning']::text[], 'Rising', 'Prompting the model to ask itself clarifying questions before answering — a form of introspection.', 'Before answering, asking "What information do I need?" and "Have I understood the question correctly?"', '"User: Is Paris in France? Model: Do I know where Paris is? Yes, it''s the capital of France. Is France a country in Europe? Yes. So yes, Paris is in France."', '[{"text":"Form of chain-of-thought reasoning.","id":"chainofthought"},{"text":"Related to ReAct prompting.","id":"reactprompting"}]'::jsonb, 'Self-ask is a form of chain-of-thought. The model reasons by questioning itself, making reasoning explicit. Effective for factual questions and knowledge retrieval. Less clear if it helps with open-ended tasks.', 'Improves accuracy on factual questions.', 'Prompt with: "Before answering, ask yourself...". Monitor for circular reasoning.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('reactprompting', 'ReAct prompting', '', '', ARRAY['Reason + Act','reasoning and action','thought-action-observation','action loop']::text[], 'Rising', 'A prompt structure where the model alternates between reasoning (thought), taking action (tool calls or steps), and observing results.', 'Planning → executing → reflecting, in a loop.', '"Thought: I need to find the GDP of France. Action: Search Google. Observation: France GDP is X. Thought: So compared to Germany... Action: Search Germany GDP. Observation: ... Thought: France is larger."', '[{"text":"Core to agent design.","id":"agents"}]'::jsonb, 'ReAct is foundational to agentic prompting. The structure forces the model to think, act, observe, and adjust. It works well with external tools (search, calculators, APIs). The observation loop creates feedback and prevents hallucination.', 'Enables agent-like behavior: planning, tool use, correction.', 'Implement with tool calling. Parse thought/action/observation. Loop until done.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('scratchpadprompting', 'Scratchpad prompting', '', '', ARRAY['working space','internal reasoning','thinking space','hidden reasoning']::text[], 'Rising', 'Explicitly allocating space in a prompt for the model to "think out loud" — write intermediate reasoning that doesn''t go in the final answer.', 'A math test where you show your work on scrap paper, then write the final answer cleanly.', 'Prompt: "Scratchpad: [Show your reasoning here] Final answer: [Clean answer]"', '[{"text":"Related to step-by-step and chain-of-thought.","id":"stepbystepprompting"}]'::jsonb, 'Scratchpads improve reasoning by separating process from output. The model can explore ideas without polluting the final response. Works for math, logic, and planning tasks. Can be formalized with explicit delimiters or just natural language.', 'Improves reliability; users only see polished final answer.', 'Add "Scratchpad:" or "Working:" section. Parse final answer separately if needed.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('outputschema', 'Output schema', '', '', ARRAY['response schema','output structure','schema definition','output template']::text[], 'Core', 'A formal definition of what fields and structure the model''s output must have — often expressed as a JSON Schema, Pydantic model, or TypeScript type.', 'A blueprint: "The house has 3 bedrooms, 2 baths, 1 kitchen."', 'Schema: {name: string, age: int, email: string}. Output must match this shape or be rejected.', '[{"text":"Enforced via structured output and JSON mode.","id":"structuredoutput"},{"text":"Overlaps with format specification.","id":"formatspecification"}]'::jsonb, 'Output schemas enable validation, parsing, and downstream automation. Combined with structured output or JSON mode, they''re near-bulletproof. Define schemas in code (Pydantic, TypeScript) or spec languages (JSON Schema). Tools like Instructor or LangChain provide helpers.', 'Zero-validation overhead. Machine-readable output by design.', 'Define schema in your language. Use Pydantic, Zod, or JSON Schema. Validate every model output.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[]),
  ('functionschemaprompting', 'Function schema prompting', '', '', ARRAY['function specification','schema prompting','tool specification','API schema']::text[], 'Rising', 'Passing a formal definition of available functions/tools to the model so it can decide which one to call and with what parameters.', 'Handing someone a phonebook: "Here are the plumbers in your area, here''s how to call them."', 'API has function "search_web(query: string, num_results: int)". Pass schema to model. Model outputs: "I''ll call search_web with query=''GDP France'' and num_results=5".', '[{"text":"Overlaps with output schema.","id":"outputschema"}]'::jsonb, 'Function schema prompting bridges language and action. The model sees formal specifications and outputs valid function calls. APIs like OpenAI''s function_call mode handle this. The model must learn to parse its own output correctly (or use structured output to enforce it).', 'Enables complex agentic workflows. Model can autonomously call APIs.', 'Define function schemas carefully. Parse model output and validate before executing.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('systemmessagedesign', 'System message design', '', '', ARRAY['system prompt design','system instruction','system context','system definition']::text[], 'Rising', 'Carefully crafting the system message that sets the overall context, persona, and rules for a model''s behavior.', 'The first page of a rulebook that defines the game for everyone.', '"You are a helpful, accurate, and concise assistant. You are an expert in Python. Refuse illegal requests. Explain clearly."', '[{"text":"Part of multi-turn management.","id":"multiturn"},{"text":"Works with assistant persona.","id":"assistantpersona"}]'::jsonb, 'System messages are powerful but subtle. They influence all downstream behavior. Good system messages are specific, consistent, and backed by examples or training. Poor ones are vague ("be helpful") or contradictory ("be honest" and "don''t say bad things" can conflict).', 'Foundation of model behavior. Consistency and brand voice start here.', 'Design carefully. Test with diverse inputs. Iterate based on user feedback.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('contextwindowmanagement', 'Context window management', '', '', ARRAY['token budgeting','context limits','memory management','context optimization']::text[], 'Rising', 'Strategically managing what information fits in the model''s context window — deciding what to include, what to summarize, what to discard.', 'Packing a suitcase with limited space: you prioritize essentials.', 'A conversation has 10 prior turns but only room for 5. Summarize the first 5 into "The user asked about X, then Y, we decided on Z."', '[{"text":"Related to token limits and truncation.","id":"tokenlimit"},{"text":"Addressed by prompt compression.","id":"promptcompression"}]'::jsonb, 'Context window size is fixed per model. You must allocate space to system message, examples, input, and history. As context fills, you lose memory. Solutions: (1) Summarize old turns, (2) Use external memory, (3) Use models with longer contexts, (4) Slide window (keep only recent turns).', 'Token cost scales with context size. Smart management = lower cost.', 'Track token usage. Implement summarization or sliding window. Choose models with sufficient context for your use case.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('promptcompression', 'Prompt compression', '', '', ARRAY['context compression','prompt condensing','information compression','context reduction']::text[], 'Rising', 'Reducing a long prompt or context to its essential meaning — preserving information while shrinking token count.', 'Summarizing a 50-page report into a 5-page executive summary.', 'A 500-token document compressed to 200 tokens via summarization or selector techniques, then used in a prompt.', '[{"text":"Solves context window management challenges.","id":"contextwindowmanagement"},{"text":"Overlaps with token optimization.","id":"tokenoptimization"}]'::jsonb, 'Compression can be lossy (summary) or lossless (clever encoding). Lossy is simpler but risks missing details. Lossless is hard (compression algorithms don''t beat LLMs at understanding semantics). Some models specifically trained for compression exist. Metrics: information retention vs. token savings.', 'Reduces cost for long-context tasks.', 'Experiment with summarization + compression. Evaluate retention with eval set.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('tokenoptimization', 'Token optimization', '', '', ARRAY['token efficiency','token reduction','efficient prompting','efficiency optimization']::text[], 'Rising', 'Minimizing token usage — both input and output — to reduce latency and cost while maintaining quality.', 'Writing a haiku instead of a sonnet: same message, fewer words.', '"What is 2+2?" (4 tokens) vs. "Please tell me the result of 2+2?" (8 tokens). Same answer, 50% fewer tokens.', '[{"text":"Part of context window management.","id":"contextwindowmanagement"},{"text":"Related to prompt compression.","id":"promptcompression"}]'::jsonb, 'Token count scales with prompt length and model output length. Optimization strategies: (1) Compress prompts, (2) Use shorter examples, (3) Limit max output tokens, (4) Cache prompts (if API supports it), (5) Choose smaller models when possible.', 'Direct cost savings. Faster responses.', 'Profile token usage. Identify bottlenecks. Compress, cache, or use smaller models.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('promptversioning', 'Prompt versioning', '', '', ARRAY['version control for prompts','prompt history','version tracking','prompt iterations']::text[], 'Rising', 'Tracking changes to prompts over time — like Git for prompts — so you can compare, revert, and understand what works.', 'Like version control for code: v1.0 was basic, v1.1 added examples, v2.0 changed approach.', 'Prompt library tracks: "customer_support_v1: 85% satisfaction. v2: 87%. v3: 89%. Ship v3."', '[{"text":"Foundation for prompt registry and management.","id":"promptregistry"},{"text":"Enables optimization workflow.","id":"promptoptimization"}]'::jsonb, 'Versioning enables A/B testing and iteration. Teams can experiment independently. Downside: managing many versions is overhead; need tooling or discipline. Cloud platforms and prompt management tools handle this.', 'Empirical improvement tracking. Data-driven decisions.', 'Use version control (Git) or prompt management tool. Tag each version with baseline metrics.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('promptregistry', 'Prompt registry', '', '', ARRAY['prompt catalog','prompt management','prompt store','prompt catalog system']::text[], 'Rising', 'A centralized system that stores, versions, and retrieves prompts — with metadata, eval results, and deployment tracking.', 'A library card catalog: find the right book, check its status, borrow it.', 'Registry: "customer_support_v2" [88% eval score] [deployed to staging] [used in 5 apps].', '[{"text":"Natural evolution of prompt library.","id":"promptlibrary"},{"text":"Supports versioning workflow.","id":"promptversioning"}]'::jsonb, 'Registries enable collaboration and governance. A data team curates prompts; product teams consume them. Tracking who uses which prompt helps impact measurement. Advanced registries integrate with eval systems and CI/CD.', 'Governance, reuse, and measurement.', 'Implement with a database or service. Add API for retrieval. Integrate with eval and deployment systems.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('dynamicprompting', 'Dynamic prompting', '', '', ARRAY['adaptive prompting','context-aware prompting','data-driven prompting','personalized prompting']::text[], 'Rising', 'Generating or modifying prompts at runtime based on user input, context, or data — not using static templates.', 'A restaurant menu that changes based on what ingredients arrived that morning.', 'If user is a beginner, use detailed prompts with examples. If expert, use terse technical prompts.', '[{"text":"Related to prompt templates and registry.","id":"prompttemplate"},{"text":"Combines with exemplar selection.","id":"exemplarselection"}]'::jsonb, 'Dynamic prompts improve relevance and efficiency. You adapt to context: user expertise, task type, history. Strategies: (1) select different templates based on routing, (2) inject context-specific examples, (3) adjust constraints dynamically.', 'Better UX through personalization.', 'Add conditional logic. Fetch examples or templates based on context. Log which prompts you generated for debugging.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('conditionalprompting', 'Conditional prompting', '', '', ARRAY['branching prompts','if-then prompts','conditional logic','branching logic']::text[], 'Rising', 'Using if-then logic in prompts: "If X, do A. Else if Y, do B."', 'A decision tree: "Is it raining? If yes, wear a jacket. If no, wear sunscreen."', '"If the query is about math, solve step-by-step. If it''s about creative writing, be imaginative. If it''s about safety, refuse."', '[{"text":"Related to dynamic prompting and routing.","id":"dynamicprompting"}]'::jsonb, 'Conditional prompting can be done at prompt level (instructions) or at orchestration level (router). Models can follow conditional instructions, but orchestration-level routing (classifying input, selecting prompt) is often more reliable.', 'Handles multiple use cases with one system.', 'Implement branching at orchestration layer. Add a classifier to route to appropriate prompt.', 'Prompting & interaction', 60, ARRAY['seed','prompting-interaction']::text[]),
  ('templatevariables', 'Template variables', '', '', ARRAY['variables','placeholders','substitution','parameter binding']::text[], 'Core', 'Placeholders in a prompt template — like {{NAME}} or {user_email} — that are filled with actual data at runtime.', 'Mad Libs: "The {{ADJECTIVE}} {{NOUN}} ran {{ADVERB}}."', 'Template: "Hello {{NAME}}, your order {{ORDER_ID}} ships {{DATE}}." Runtime fills in actual values.', '[{"text":"Part of prompt template design.","id":"prompttemplate"}]'::jsonb, 'Variables separate static structure from dynamic data. They prevent prompt injection if used correctly (validate input before substitution) and make templates reusable. Common implementations: string formatting, Jinja, custom systems.', 'Clean, scalable prompting.', 'Define variables clearly. Validate and sanitize input before substitution.', 'Prompting & interaction', 80, ARRAY['seed','prompting-interaction']::text[])
